async function prepareSend(
	_,
	recipientAddress,
	amount,
	addressType,
	$walletAssets,
	availableBalance,
	estimatedFees,
	limits,
	useMainUnit,
	convertToSatoshis,
	description,
	resetForm,
	showSuccessMessage,
	getCleanAddress,
	handleDirectBitcoinSend,
	passkeyContext,
	getTransactionReason,
	showPasskeyVerification
) {
	const validationParams = {
		recipientAddress: $.get(recipientAddress),
		amount: $.get(amount),
		addressType: $.get(addressType),
		selectedAsset: $walletAssets().selectedAsset,
		availableBalance: $.get(availableBalance),
		estimatedFees: $.get(estimatedFees),
		limits: $.get(limits),
		useMainUnit: $.get(useMainUnit)
	};

	const validation = validateForm(validationParams);

	if (!validation.isValid) {
		walletStore.updateSendForm({ validationError: validation.error });
		return;
	}

	try {
		walletStore.updateSendForm({ isLoading: true, validationError: null });

		const amountSats = convertToSatoshis($.get(amount));
		const currentAsset = $walletAssets().selectedAsset;

		if (currentAsset === "L-BTC" || currentAsset === "USDt") {
			if ($.get(addressType) === "bolt12") {
				const prepared = await prepareBolt12Payment($.get(recipientAddress), amountSats, $.get(description));

				walletStore.updateSendForm({ preparedTransaction: prepared });
			} else if ($.get(addressType) === "lnurlPay") {
				const lnurlPrepare = await prepareLnurlPayment($.get(recipientAddress), amountSats, $.get(description));
				const lnurlResult = await executeLnurlPayment(lnurlPrepare);

				console.log("LNURL-Pay completed:", lnurlResult);
				resetForm();
				showSuccessMessage({ payment: { id: "lnurl-success" } });
				return;
			} else {
				const cleanDestination = getCleanAddress($.get(recipientAddress));

				const prepareParams = {
					destination: cleanDestination,
					amount: currentAsset === "USDt"
						? {
							type: "asset",
							assetId: getAssetId("USDT"),
							receiverAmount: amountSats / 100_000_000,
							estimateAssetFees: false
						}
						: {
							type: "bitcoin",
							receiverAmountSat: amountSats
						}
				};

				const prepared = await prepareSendPayment(prepareParams);

				walletStore.updateSendForm({ preparedTransaction: prepared });
			}
		} else if (currentAsset === "BTC") {
			await handleDirectBitcoinSend(amountSats);
			return;
		}

		$.set(
			passkeyContext,
			{
				operation: "send",
				amount: amountSats,
				destination: $.get(recipientAddress),
				asset: currentAsset,
				reason: getTransactionReason()
			},
			true
		);

		$.set(showPasskeyVerification, true);
	} catch(err) {
		console.error("Failed to prepare transaction:", err);

		walletStore.updateSendForm({
			validationError: err instanceof Error ? err.message : "Failed to prepare transaction",
			isLoading: false
		});
	} finally {
		walletStore.updateSendForm({ isLoading: false });
	}
}

